={{ (() => {
  const sub = $('Map Typeform Answers').first().json.submission;
  const pick = $('Pick Route & Priority').first().json;
  const cfg = $('Config · Routing Rules').first().json;
  const route = cfg.routing[pick.route_key] ?? cfg.routing.default;
  const saved = $json.airtable_saved !== false;
  const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const cut = (v, n) => { const t = esc(v); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
  const at = $('Upsert Record in Airtable').params;
  const baseId = (String(at.base?.value ?? '').match(/app[A-Za-z0-9]+/) || [at.base?.value])[0];
  const tableId = (String(at.table?.value ?? '').match(/tbl[A-Za-z0-9]+/) || [at.table?.value])[0];
  const recordUrl = saved && $json.id ? 'https://airtable.com/' + baseId + '/' + tableId + '/' + $json.id : '';
  const earlier = $('Find Earlier Submissions').all().map(i => i.json).filter(r => r.id);
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: (pick.priority === 'HOT' ? '🔥 ' : '🆕 ') + 'New ' + route.label + ' inquiry: ' + String(sub.full_name || 'Unknown').slice(0, 80), emoji: true } },
    { type: 'section', text: { type: 'mrkdwn', text: '<@' + route.owner_slack_id + '> this one is yours. *Priority:* ' + (pick.priority === 'HOT' ? '🔥 HOT' : 'Normal') } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Name*\n' + cut(sub.full_name || '-', 200) },
      { type: 'mrkdwn', text: '*Email*\n' + cut(sub.email, 200) },
      { type: 'mrkdwn', text: '*Company*\n' + cut(sub.company || '-', 200) },
      { type: 'mrkdwn', text: '*Inquiry type*\n' + cut(sub.inquiry_type || '-', 200) },
      { type: 'mrkdwn', text: '*Team size*\n' + cut(sub.team_size || '-', 100) },
      { type: 'mrkdwn', text: '*Budget*\n' + cut(sub.budget || '-', 100) }
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: '*Details*\n' + (cut(sub.details, 2800) || '_none_') } }
  ];
  if (earlier.length) {
    const last = earlier[0];
    blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: ':repeat: Returning contact: ' + earlier.length + (earlier.length >= 5 ? '+' : '') + ' earlier submission' + (earlier.length === 1 ? '' : 's') + '. Latest ' + esc(String(last['Submitted At'] ?? '').slice(0, 10)) + ' · ' + esc(last['Inquiry Type'] || '-') + ' · status ' + esc(last.Status || '-') } ] });
  }
  blocks.push({ type: 'context', elements: [ { type: 'mrkdwn', text: 'Submitted ' + esc(sub.submitted_at) + ' · Response ' + esc(sub.response_id) + (sub.utm_source ? ' · Source ' + esc(sub.utm_source) : '') } ] });
  if (recordUrl) {
    blocks.push({ type: 'actions', elements: [ { type: 'button', text: { type: 'plain_text', text: 'Open in Airtable' }, url: recordUrl, style: 'primary' } ] });
  } else {
    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: *NOT saved to Airtable* (' + cut($json.airtable_error || 'unknown error', 200) + '). This message is the only copy; the team has been alerted by email.' } });
  }
  return blocks;
})() }}

={{ (() => {
  const cfg = $('SLA Settings').first().json;
  const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const at = $('Find Overdue Leads').params;
  const baseId = (String(at.base?.value ?? '').match(/app[A-Za-z0-9]+/) || [at.base?.value])[0];
  const tableId = (String(at.table?.value ?? '').match(/tbl[A-Za-z0-9]+/) || [at.table?.value])[0];
  const level = (Number($json['Reminders Sent']) || 0) + 1;
  const mins = Math.round($now.diff(DateTime.fromISO(String($json['Submitted At'] ?? '')), 'minutes').minutes);
  const age = Number.isNaN(mins) ? 'a while' : (mins >= 120 ? Math.floor(mins / 60) + ' h ' + (mins % 60) + ' min' : mins + ' min');
  const owner = $json['Owner Slack ID'] ? '<@' + $json['Owner Slack ID'] + '>' : 'Team';
  let text = ':alarm_clock: ' + owner + ' reminder ' + level + ': *' + esc($json['Full Name'] || 'Unknown') + '*' + ($json.Company ? ' (' + esc($json.Company) + ')' : '') +
    ' is still *New* after ' + age + '. Priority: ' + esc($json.Priority || 'NORMAL') + '. <https://airtable.com/' + baseId + '/' + tableId + '/' + $json.id + '|Open in Airtable>';
  if (level >= Number(cfg.max_reminders) && cfg.manager_slack_id) text += '\n:rotating_light: Escalating to <@' + cfg.manager_slack_id + '>.';
  return text;
})() }}

parameters.errorMessage:
={{ (() => {
  const all = $('Build Reminder').all().map(i => i.json);
  const sent = new Set($('Mark Reminder Sent').isExecuted ? $('Mark Reminder Sent').all().map(i => i.json.id) : []);
  const failed = all.filter(r => !sent.has(r.record_id));
  return '[WARNING] ' + failed.length + ' of ' + all.length + ' SLA reminder(s) could not be posted to Slack (' + String($json.error ?? 'unknown error').slice(0, 200) + '). They will be retried in 15 minutes: ' + failed.map(r => r.lead_label).join(', ').slice(0, 1000);
})() }}

